using System;

public class Number
{
    private readonly double value;

    public Number(double value)
    {
        this.value = value;
    }

    public T ConvertTo<T>()
    {
        return (T)ConvertTo(typeof(T));
    }

    public object ConvertTo(Type convertToType)
    {
        if (convertToType == typeof(int))
        {
            return (int)value;
        }
        else if (convertToType == typeof(string))
        {
            return value.ToString();
        }
        else if (convertToType == typeof(double))
        {
            return value;
        }
        else
        {
            throw new InvalidCastException($"Cannot convert Number to {convertToType.Name}");
        }
    }
}

