import json

def extract_text_from_json(data):
    """
    Recursively extracts and returns all string values from a nested JSON structure.

    :param data: A JSON data structure (nested dict/list).
    :return: A list of string values found within the JSON structure.
    """
    text_values = []

    if isinstance(data, str):
        text_values.append(data)
    elif isinstance(data, dict):
        for value in data.values():
            text_values.extend(extract_text_from_json(value))
    elif isinstance(data, list):
        for item in data:
            text_values.extend(extract_text_from_json(item))

    return text_values


def main():
    """
    Reads a JSON file, extracts all string values, and prints them to the console.
    """
    file_name = "your_file_name.json"

    try:
        with open(file_name, 'r', encoding='utf-8') as file:
            json_data = json.load(file)
    except json.JSONDecodeError as e:
        print(f"Failed to decode JSON: {e}")
        return
    except FileNotFoundError:
        print(f"File not found: {file_name}")
        return

    all_text = extract_text_from_json(json_data)

    for text in all_text:
        print(text)


if __name__ == "__main__":
    main()
