			reg <<= 1;

			if (topBit)
				reg ^= _key;
		}
		_table [i] = reg;
	}
}

void PolyChecksum::putBytes(void* bytes, size_t dataSize)
{
    unsigned char* ptr = (unsigned char*) bytes;

    for (int i = 0; i < dataSize; i++)
    {
        unsigned byte = (unsigned) ptr[i];
        unsigned top = _register >> 24;
        top ^= byte;

        _register = (_register << 8) ^ _table [top];
    }
