def character_count(s):
    """
    Returns a dictionary with characters as keys and their frequencies in the string as values.

    :param s: A string consisting of lowercase English letters.
    :return: A dictionary with character frequencies.
    """
    result = {}
    for char in s:
        if char in result:
            result[char] += 1
        else:
            result[char] = 1
    return result

