def find_prime_factors(n):
    """
    Returns a list of unique prime factors of the given integer n in ascending order.

    :param n: An integer whose prime factors are to be found.
    :return: A list of unique prime factors of n.
    """
    if n == 0:
        return []

    def prime_factors(num):
        i = 2
        factors = []
        while i * i <= abs(num):
            if num % i:
                i += 1
            else:
                num //= i
                if i not in factors:
                    factors.append(i)
        if abs(num) > 1 and abs(num) not in factors:
            factors.append(abs(num))
        return factors

    return prime_factors(n)
