class LoggerManager:
    def __init__(self):
        self.logger = logging.getLogger()
        self.logger.setLevel(logging.INFO)  # Default logging level

    def set_logging_level(self, debug):
        if debug:
            self.logger.setLevel(logging.DEBUG)
        else:
            self.logger.setLevel(logging.INFO)

    def add_logging_output(self, output):
        handler = logging.StreamHandler(output)
        self.logger.addHandler(handler)

    def remove_logging_output(self, output):
        for handler in self.logger.handlers:
            if handler.stream == output:
                self.logger.removeHandler(handler)

    def clear_logging_outputs(self):
        for handler in self.logger.handlers[:]:
            self.logger.removeHandler(handler)

    def execute(self):
        # Simulate the execution of the logging system
        self.logger.debug('Debug message')
        self.logger.info('Info message')
        self.logger.warning('Warning message')
        self.logger.error('Error message')
        self.logger.critical('Critical message')

# Example usage
