class Calculator:
    def add(self, numbers):
        """Return the sum of a list of numbers."""
        return sum(numbers)

    def subtract(self, numbers):
        """Return the result of subtracting each subsequent number from the first."""
        result = numbers[0]
        for number in numbers[1:]:
            result -= number
        return result

    def multiply(self, numbers):
        """Return the product of a list of numbers."""
        result = 1
        for number in numbers:
            result *= number
        return result

    def divide(self, numbers):
        """Return the result of dividing the first number by each subsequent number."""
        result = numbers[0]
        for number in numbers[1:]:
            if number == 0:
                raise ValueError("Cannot divide by zero.")
            result /= number
        return result

    def operate(self, operator, numbers):
        """Apply the specified arithmetic operation to the list of numbers."""
        if not numbers:
            raise ValueError("The list of numbers must not be empty.")

        if operator == '+':
            return self.add(numbers)
        elif operator == '-':
            return self.subtract(numbers)
        elif operator == '*':
            return self.multiply(numbers)
        elif operator == '/':
            return self.divide(numbers)
        else:
            raise ValueError(f"Unsupported operator: {operator}")
