def format_duration(seconds):
    """
    Converts a given number of seconds into a human-readable format.

    Parameters:
    seconds (int): The total number of seconds to be converted.

    Returns:
    str: A string representing the duration in the format "X hours, Y minutes, and Z seconds",
         omitting any part of the duration that is zero.
    """
    hours = minutes = remaining_seconds = 0

    if seconds >= 3600:
        hours = seconds // 3600
        seconds %= 3600
    if seconds >= 60:
        minutes = seconds // 60
        remaining_seconds = seconds % 60
    else:
        remaining_seconds = seconds

    time_parts = []

    if hours > 0:
        time_parts.append(f"{hours} hour{'s' if hours > 1 else ''}")
    if minutes > 0:
        time_parts.append(f"{minutes} minute{'s' if minutes > 1 else ''}")
    if remaining_seconds > 0:
        time_parts.append(f"{remaining_seconds} second{'s' if remaining_seconds > 1 else ''}")

    if len(time_parts) > 2:
        return ', '.join(time_parts[:-1]) + f", and {time_parts[-1]}"
    elif len(time_parts) == 2:
        return f"{time_parts[0]} and {time_parts[1]}"
    elif len(time_parts) == 1:
        return time_parts[0]
    else:
        return "0 seconds"
