def calculate_grade(score):
    """
    Determines the letter grade based on the numerical score.

    Parameters:
    score (int or float): The student's numerical score.

    Returns:
    str: The corresponding letter grade ('A', 'B', 'C', 'D', 'F').

    Raises:
    ValueError: If the score is not a number or is outside the range 0 to 100 inclusive.
    """
    if not isinstance(score, (int, float)):
        raise ValueError("Invalid input: Score must be a number.")
    if not (0 <= score <= 100):
        raise ValueError("Invalid input: Score must be between 0 and 100 inclusive.")

    if 90 <= score <= 100:
        return 'A'
    elif 80 <= score < 90:
        return 'B'
    elif 70 <= score < 80:
        return 'C'
    elif 60 <= score < 70:
        return 'D'
    else:
        return 'F'
