class BankAccount:
    def __init__(self, name, opening_balance=0.0):
        """Initialize a bank account with a name and an optional opening balance."""
        self.name = name
        self.balance = opening_balance

    def deposit(self, amount):
        """Deposit a positive amount into the account and print the transaction details."""
        if amount > 0:
            self.balance += amount
            print(f"Deposited ${amount:.2f}. New balance is ${self.balance:.2f}.")
        else:
            print("Deposit amount must be positive.")

    def withdraw(self, amount):
        """Withdraw a positive amount from the account if sufficient funds are available and print the transaction details."""
        if amount > 0:
            if self.balance >= amount:
                self.balance -= amount
                print(f"Withdrew ${amount:.2f}. New balance is ${self.balance:.2f}.")
            else:
                print("Insufficient funds.")
        else:
            print("Withdrawal amount must be positive.")

    def get_balance(self):
        """Return and print the current balance of the account."""
        print(f"Current balance is ${self.balance:.2f}.")
        return self.balance

    def apply_interest(self, rate):
        """Apply a non-negative interest rate to the account balance and print the transaction details."""
        if rate >= 0:
            interest = self.balance * (rate / 100)
            self.balance += interest
            print(f"Applied {rate}% interest. New balance is ${self.balance:.2f}.")
        else:
            print("Interest rate must be non-negative.")
