import { useState } from 'react';

const useCustomProgress = (initialProgress) => {
  const [progress, setProgress] = useState(initialProgress);

  const startProgress = () => {
    setProgress(0);
  };

  const incrementProgress = (amount = 10) => {
    setProgress((prevProgress) => Math.min(prevProgress + amount, 100));
  };

  const completeProgress = () => {
    setProgress(100);
  };

  return {
    progress,
    startProgress,
    incrementProgress,
    completeProgress,
  };
};

export default useCustomProgress;
```

