  return Math.round(temp * 100) / 100;
}

// Function to convert Celsius to Kelvin
function celsiusToKelvin(celsius) {
  return celsius + 273.15;
}

// Function to convert Kelvin to Celsius
function kelvinToCelsius(kelvin) {
  return kelvin - 273.15;
}

// Function to display the menu and handle user input
function displayMenu() {
  console.log("Temperature Conversion Menu");
  console.log("1. Celsius to Kelvin");
  console.log("2. Kelvin to Celsius");
  console.log("3. Exit");
}

// Function to handle the conversion based on user input
function handleConversion(type) {
  let input = parseFloat(prompt("Enter the temperature value:"));

  while (isNaN(input)) {
    input = parseFloat(prompt("Invalid input. Enter a valid temperature value:"));
  }

  if (isValidTemperature(input)) {
    let convertedTemp;

    if (type === 1) {
      convertedTemp = celsiusToKelvin(input);
      console.log(`${input} Celsius = ${roundTemperature(convertedTemp)} Kelvin`);
    } else if (type === 2) {
      convertedTemp = kelvinToCelsius(input);
      console.log(`${input} Kelvin = ${roundTemperature(convertedTemp)} Celsius`);
    }

    let choice = prompt("Perform another conversion? (Y/N)");

    while (choice.toLowerCase() !== "y" && choice.toLowerCase() !== "n") {
      choice = prompt("Invalid choice. Perform another conversion? (Y/N)");
    }

    if (choice.toLowerCase() === "y") {
      startConversion();
    } else {
      console.log("Goodbye!");
    }
  } else {
    console.log("Invalid temperature. Temperature must be within the range of -273.15 to 1000 Celsius.");
    startConversion();
  }
}

// Function to start the conversion process
function startConversion() {
  displayMenu();
  let choice = parseInt(prompt("Enter your choice:"));

  while (choice !== 1 && choice !== 2 && choice !== 3) {
    choice = parseInt(prompt("Invalid choice. Enter your choice:"));
  }

  if (choice === 1) {
    handleConversion(1);
  } else if (choice === 2) {
    handleConversion(2);
  } else {
    console.log("Goodbye!");
  }
}

// Start the program
startConversion();
```

This program allows the user to choose whether to convert from Celsius to Kelvin or from Kelvin to Celsius. It validates the input temperature and displays an error message if the input is invalid. It also rounds the converted temperature to two decimal places. The program handles non-numeric and invalid input by displaying error messages and asking the user to enter valid input again. It provides an option for the user to perform another conversion or exit the program.

