def is_prime(num):
    """Returns True if the number is prime, otherwise False."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def largest_prime_factor(n):
    """Returns the largest prime factor of the given integer n."""
    largest_factor = None
    while n % 2 == 0:
        largest_factor = 2
        n //= 2
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            largest_factor = i
            n //= i
    if n > 2:
        largest_factor = n
    return largest_factor

# Example usage:
number = 13195
print(f"The largest prime factor of {number} is {largest_prime_factor(number)}")
