```python
def is_prime(num):
    """Check if a number is prime."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def sum_of_primes(n):
    """Return the sum of all prime numbers less than or equal to n."""
    total = 0
    for i in range(2, n + 1):
        if is_prime(i):
            total += i
    return total

# Example usage:
