	virtual void on_timer() override
	{
		_led.toggle();
	}

private:
	FastPinType<Board::DigitalPin::LED>::TYPE _led;
};

int main()
{
	sei();
	Handler handler;
	TIMER_TYPE timer{handler};
	timer.begin(PRESCALER, COUNTER);

	while (true) ;
}

