def flattenHierarchy(data):
    """
    Flattens a hierarchical JSON object of categories and subcategories into a list of strings.

    Parameters:
    data (dict): A dictionary representing the hierarchy of categories and subcategories.

    Returns:
    list: A list of strings, each representing a unique subcategory in the format "Category > Subcategory > Item".
    """
    result = []
    for category, subcategories in data.items():
        for subcategory, items in subcategories.items():
            for item in items:
                result.append(f"{category} > {subcategory} > {item}")
