def sum_of_primes(n):
    """
    Computes the sum of all prime numbers less than or equal to n.

    Parameters:
    n (int): The upper limit integer.

    Returns:
    int: The sum of all prime numbers less than or equal to n.
    """
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    return sum(x for x in range(2, n + 1) if is_prime(x))
