import pandas as pd
from datetime import datetime
from collections import Counter

class CRM:
    def __init__(self):
        self.customers_df = pd.DataFrame(columns=['Name', 'Age', 'Location', 'Email', 'Preferred_Platform', 'Interaction_History', 'Last_Interaction'])

    def add_customer(self, name, age, location, email, preferred_platform):
        customer_info = {'Name': name, 'Age': age, 'Location': location, 'Email': email, 'Preferred_Platform': preferred_platform, 'Interaction_History': [], 'Last_Interaction': None}
        self.customers_df = self.customers_df.append(customer_info, ignore_index=True)

    def update_interaction(self, name, interaction, sentiment, date=None):
        if date is None:
            date = datetime.now()

        idx = self.customers_df[self.customers_df['Name'] == name].index[0]
        self.customers_df.at[idx, 'Interaction_History'].append((date, interaction, sentiment))
        self.customers_df.at[idx, 'Last_Interaction'] = date

    def search_customer(self, **kwargs):
        search_df = self.customers_df

        for kwarg in kwargs:
            if kwarg in self.customers_df.columns:
                search_df = search_df.loc[search_df[kwarg] == kwargs[kwarg]]

        if search_df.empty:
            print("No customer found.")
        else:
            return search_df

    def sort_customer(self, sort_by='Age', ascending=True):
        sorted_df = self.customers_df.sort_values(by=sort_by, ascending=ascending)
        return sorted_df

    def interaction_statistics(self, name):
        idx = self.customers_df[self.customers_df['Name'] == name].index[0]
        interactions = self.customers_df.at[idx, 'Interaction_History']

        sentiments = [inter[2] for inter in interactions]
        sentiment_statistics = Counter(sentiments)

        return sentiment_statistics
