import json

def extract_integers(json_str):
    """
    Parses a JSON string and returns a dictionary containing only the key-value pairs
    where the value is an integer. Recursively parses nested dictionaries.

    :param json_str: A string representing a JSON object.
    :return: A dictionary with integer values.
    """
    def parse_dict(d):
        result = {}
        for key, value in d.items():
            if isinstance(value, int):
                result[key] = value
            elif isinstance(value, dict):
                nested_result = parse_dict(value)
                if nested_result:
                    result[key] = nested_result
        return result

    data = json.loads(json_str)
    return parse_dict(data)
